package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DefaultAcrValuesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property default acr values of oauth client ")
  void test_default_acr_values_v_o_builder() {
    Assertions.assertFalse(DefaultAcrValuesVO.nullValue().getDefaultAcrValues().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(DefaultAcrValuesVO.tryFrom(null).getDefaultAcrValues().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        DefaultAcrValuesVO.from("one").getDefaultAcrValues().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DefaultAcrValuesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DefaultAcrValuesVO.from("one").toString());
  }
}
